const u=JSON.parse('{"workId":"guo-yu","chapter":{"id":"guo-yu_ch-2","workId":"guo-yu","order":2,"title":"周語中","difficulty":4,"estimatedMinutes":17,"passageIds":["guo-yu_ch-2_p-1","guo-yu_ch-2_p-2","guo-yu_ch-2_p-3","guo-yu_ch-2_p-4","guo-yu_ch-2_p-5","guo-yu_ch-2_p-6","guo-yu_ch-2_p-7","guo-yu_ch-2_p-8","guo-yu_ch-2_p-9","guo-yu_ch-2_p-10","guo-yu_ch-2_p-11","guo-yu_ch-2_p-12","guo-yu_ch-2_p-13","guo-yu_ch-2_p-14","guo-yu_ch-2_p-15","guo-yu_ch-2_p-16","guo-yu_ch-2_p-17","guo-yu_ch-2_p-18","guo-yu_ch-2_p-19","guo-yu_ch-2_p-20","guo-yu_ch-2_p-21","guo-yu_ch-2_p-22","guo-yu_ch-2_p-23","guo-yu_ch-2_p-24","guo-yu_ch-2_p-25","guo-yu_ch-2_p-26","guo-yu_ch-2_p-27","guo-yu_ch-2_p-28","guo-yu_ch-2_p-29","guo-yu_ch-2_p-30"],"tags":[]},"passages":[{"id":"guo-yu_ch-2_p-1","chapterId":"guo-yu_ch-2","order":1,"canonicalText":"襄王十三年，鄭人伐滑。王使遊孫伯請滑，鄭人執之。王怒，將以狄伐鄭。富辰諫曰：「不可。古人有言曰：『兄弟鬩於牆，外禦其務。』鄭，周之伯父也，有小怨而棄之，引戎狄以伐同姓，是自拔其本也。且王怒不可長，狄德不可恃，願王圖之。」王不聽，遂以狄伐鄭。","sentenceIds":["guo-yu_ch-2_p-1_s-1","guo-yu_ch-2_p-1_s-2","guo-yu_ch-2_p-1_s-3","guo-yu_ch-2_p-1_s-4","guo-yu_ch-2_p-1_s-5","guo-yu_ch-2_p-1_s-6","guo-yu_ch-2_p-1_s-7","guo-yu_ch-2_p-1_s-8"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周襄王十三年，鄭國起兵攻打滑國。周襄王派遣使臣遊孫伯前往鄭國為滑國說情求和，鄭國人竟然蠻橫扣押了周王室的使臣！周襄王大發雷霆，準備勾結引導外圍少數民族狄人部隊去攻打討伐鄭國！賢臣富辰極力進諫說：大王絕對不可這樣做啊！古人有千古名言說：兄弟在家門高牆之內縱有爭吵打架（兄弟鬩於牆），對外遭遇強盜侵略時必定齊心協力共同抵禦外侮（外禦其侮）！鄭國與我們大周是同宗血脈的伯父之國，怎能因為一點細小的怨恨摩擦就徹底拋棄同胞兄弟，反而引導野蠻的戎狄部隊來攻打自己同姓的宗親邦國呢？這是在親手拔除我們自身的立國根本啊！況且君王的情緒暴怒不可肆意放縱，狄人的野蠻天性絕對不可盲目依賴，希望大王深思熟慮慎重決策！周襄王根本不聽勸諫，執意引導狄人軍隊攻打了鄭國。","analysis":"【題解與兄弟鬩於牆外禦其侮富辰諫襄王以狄伐鄭】本段為中華民族團結禦侮名言「兄弟鬩於牆，外禦其侮（出自《詩經・小雅・常棣》）」在《國語》中的經典政治運用！\\\\n【詞義訓詁】「富辰」：周襄王時深謀遠慮之賢臣；「兄弟鬩於牆外禦其務」：務通侮；內部有矛盾對外必須一致團結；「自拔其本」：引狼入室自毀同姓屏障。\\\\n【戰略底線思維】內部宗親地緣矛盾屬於人民內部矛盾，切忌為了局部私怨勾引外部強敵（引狄伐鄭），否則終將引狼入室、釀成滔天大禍。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-2","chapterId":"guo-yu_ch-2","order":2,"canonicalText":"王德狄人，將以其女為後。富辰諫曰：「不可。夫婚姻，禍福之階也。由之利內則福，利外則取禍。今王以狄女為後，狄貪而無信，必生內變。且諸侯聞之，皆謂王棄宗族而親蠻夷，其誰肯輔王？願王熟思之。」王不聽，遂立狄女為後。","sentenceIds":["guo-yu_ch-2_p-2_s-1","guo-yu_ch-2_p-2_s-2","guo-yu_ch-2_p-2_s-3","guo-yu_ch-2_p-2_s-4","guo-yu_ch-2_p-2_s-5","guo-yu_ch-2_p-2_s-6","guo-yu_ch-2_p-2_s-7","guo-yu_ch-2_p-2_s-8"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周襄王因為感激狄人的恩德，打算娶狄人的女子作為王后。大夫富辰勸諫說：這絕對不行。婚姻這件事，是引發禍患或帶來福氣的階梯。通過婚姻使內部宗族獲利就會帶來福氣，使外部異族獲利就會招致禍患。如今大王您要立狄人的女子為王后，狄人本性貪婪且不講信義，將來必然會引發宮廷內部的變亂。況且各國諸侯聽說了這件事，都會認為大王您拋棄了同宗的親族而去親近蠻夷，這樣一來還有誰肯來輔佐您呢？希望大王您能深思熟慮。周襄王沒有聽從勸告，最終還是立了狄女為王后。","analysis":"【訓詁與名物】：「德」在此作動詞，感激恩德。「狄人」指古代北方的少數民族。「後」即王后。「富辰」為周朝的大夫。「階」指階梯、途徑。「利內」指利益歸於同宗或內部。「利外」指利益歸於外族。「宗族」此處泛指姬姓的諸侯國。「蠻夷」為中原華夏對周邊少數民族的泛稱。\\\\n\\\\n【章法與結構】：本段以富辰的諫言為核心。開篇交代襄王「德狄立後」的起因；中間富辰的諫言分為三個層次：首先提出「婚姻為禍福之階」的總命題，其次指出狄人「貪而無信必生內變」的直接危機，最後從天下大局出發，指出「棄宗族親蠻夷」將導致諸侯離心的嚴重後果；結尾以襄王「不聽」作結，預示了災難的來臨。\\\\n\\\\n【思想與義理】：這段對話深刻反映了先秦時期華夏與夷狄的「華夷之辨」觀念，以及婚姻在古代政治中的特殊地位。在宗法制度下，天子的婚姻絕非個人私事，而是關係到天下政治格局的聯盟。富辰極力反對與狄人聯姻，不僅是因為狄人的道德特徵（貪而無信），更是因為這違背了「親親」的宗法原則。天子如果背棄了以血緣和文化為紐帶的諸侯盟友，轉而依賴異族，必然會喪失政治上的正統性與號召力。這種深謀遠慮的政治危機感，在後來的歷史中被反覆印證。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-3","chapterId":"guo-yu_ch-2","order":3,"canonicalText":"王曰：「利何如而內，何如而外？」對曰：「尊貴、明賢、庸勛、長老、愛親、禮新、親舊。然則民莫不協，神無不享，是謂利內。今狄無是七者，而王親之，是利外也。利外必亡。」","sentenceIds":["guo-yu_ch-2_p-3_s-1","guo-yu_ch-2_p-3_s-2","guo-yu_ch-2_p-3_s-3","guo-yu_ch-2_p-3_s-4","guo-yu_ch-2_p-3_s-5","guo-yu_ch-2_p-3_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周王問道：要怎麼做纔算是使內部獲利，怎麼做纔算是使外部獲利呢？富辰回答說：尊重地位高貴的人、表彰有才德的人、任用有功勳的人、敬重年長的人、愛護自己的親族、以禮對待新結交的朋友、親近舊有的故交。如果能做到這七點，那麼天下百姓就沒有不和睦協作的，神明也沒有不來享用祭祀的，這就叫做使內部獲利。如今狄人根本不具備這七種美德，而大王您卻要去親近他們，這就叫做使外部獲利。使外部獲利必然會導致國家的滅亡。","analysis":"【訓詁與名物】：「明賢」指顯揚、表彰賢能的人。「庸勛」指任用、酬報有功勞的人，庸同用。「長老」作動詞，指敬重老人。「親舊」指親近故交。「協」指和睦、協作。「享」指神明歆享祭品。「利內」指鞏固國家內部的政治與道德秩序。「利外」指將利益輸送給不守禮法的外部勢力。\\\\n\\\\n【章法與結構】：此段為問答體，富辰對「利內」與「利外」進行了極其嚴密的哲學與政治定義。他連用七個動賓結構的詞組（尊貴、明賢……），構成了一套完整的傳統道德與政治準則矩陣。隨後他用「然則」推導出「民協神享」的理想社會狀態。最後，他將這套標準作為尺子去衡量「狄人」，得出「狄無是七者」的結論，並發出「利外必亡」的嚴厲警告。說理氣勢磅礡，邏輯嚴密。\\\\n\\\\n【思想與義理】：這段論述是西周禮樂文明與儒家政治倫理的集中體現。富辰所提出的「七德」，涵蓋了階級秩序（尊貴、庸勛）、道德修養（明賢、長老）以及人際關係（愛親、禮新、親舊），這構成了當時社會內部穩定（利內）的基石。他認為，華夏與夷狄的根本區別不在於血統，而在於是否認同並實踐這套禮義道德。結交沒有這套道德約束的異族（利外），就等於引狼入室，必然會導致文明秩序的崩潰與國家的滅亡。這是一種深刻的文化本位主義。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-4","chapterId":"guo-yu_ch-2","order":4,"canonicalText":"十八年，王黜狄後。狄人來誅殺譚伯。富辰曰：「昔吾驟諫王，王弗從，以及此難。若我不出，王其以我為懟乎！」遂出，佐王戰，死之。","sentenceIds":["guo-yu_ch-2_p-4_s-1","guo-yu_ch-2_p-4_s-2","guo-yu_ch-2_p-4_s-3","guo-yu_ch-2_p-4_s-4","guo-yu_ch-2_p-4_s-5"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"到了周襄王十八年的時候，周襄王廢黜了狄人王后。狄人因此大怒，派兵前來攻打周朝，並殺死了大夫譚伯。富辰見狀說道：從前我屢次勸諫大王，大王都沒有聽從，才導致了今天這場災難。現在如果我不挺身而出，大王恐怕會以為我還在怨恨他當初不聽我的勸諫吧！於是，富辰挺身而出，輔佐周王與狄人作戰，最終光榮戰死在沙場上。","analysis":"【訓詁與名物】：「黜」指廢黜、罷免。「譚伯」周朝的大夫。「驟」指屢次、多次。「難」指災難、戰亂。「出」指出戰、挺身而出。「其……乎」表推測語氣，恐怕……吧。「懟」指怨恨。「佐」指輔佐、幫助。「死之」指為這件事（保衛周王與國家）而死。\\\\n\\\\n【章法與結構】：本段敘事極其悲壯。開頭先以簡潔的筆觸交代了預言的應驗：立狄後導致了最終的衝突（黜後、狄人犯周、殺譚伯）。在國家生死存亡的關頭，鏡頭聚焦於曾經苦諫不入的富辰。富辰的獨白「若我不出……」是全段的靈魂，隨後「遂出，佐王戰，死之」這九個字，節奏急促，力透紙背，將一個孤忠之臣的形象定格在了歷史的長卷中。\\\\n\\\\n【思想與義理】：富辰的選擇完美詮釋了中國古代「文死諫，武死戰」的最高忠臣境界與「殺身成仁」的道德理想。當初他逆鱗苦諫，展現的是政治家的遠見與「智」；如今國難當頭，他沒有選擇冷眼旁觀或落井下石以證明自己的正確，而是選擇了以死殉國，這展現的是人臣的「忠」與「勇」。他用自己的生命打破了君臣之間可能存在的猜忌（以我為懟），維護了君臣之義與國家尊嚴。這是一種超越了個人恩怨的崇高人格美。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-5","chapterId":"guo-yu_ch-2","order":5,"canonicalText":"初，惠後欲立王子帶，故以其黨啟狄人。狄人遂入，周王乃出居於鄭，晉文公納之。","sentenceIds":["guo-yu_ch-2_p-5_s-1","guo-yu_ch-2_p-5_s-2"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"起初，周惠王之後惠後一心想要冊立自己的親生兒子王子帶為天子，所以惠後的同黨在宮廷內部充當內應引導狄人攻入洛邑。狄人大軍於是輕易攻入京師，周襄王被迫出逃流亡避難於鄭國，直到晉文公起兵勤王才平定內亂並迎奉天子復位。","analysis":"【題解與王子帶內通狄人襄王出奔】本段記錄周襄王時王室內亂之全過程：後黨宮廷政變引狼入室，周天子再度出奔，依託晉文公勤王方得平定。\\\\n【詞義訓詁】「惠後」：周惠王之後；「啟狄人」：充當內應引導狄人入侵；「出居於鄭」：天子流亡鄭國；「晉文公納之」：晉文公出兵平叛迎立襄王。\\\\n【宮廷政變的危害】統治集團內部的權力鬥爭若勾結外敵勢力，必將引發國家主權與安全的全面危機，給百姓帶來深重災難。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-6","chapterId":"guo-yu_ch-2","order":6,"canonicalText":"晉文公既定襄王於郟，王勞之以地，辭，請隧焉。王不許，曰：「昔我先王之有天下也，規方千里以為甸服，以供天子。諸侯之有位，各有等差。王者之制，生有明德，死有明名，隧者天子之禮也。叔父雖有大功，未可踰天子之禮也。」文公遂受地而還。","sentenceIds":["guo-yu_ch-2_p-6_s-1","guo-yu_ch-2_p-6_s-2","guo-yu_ch-2_p-6_s-3","guo-yu_ch-2_p-6_s-4","guo-yu_ch-2_p-6_s-5","guo-yu_ch-2_p-6_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"晉文公在郟地平定了王室的叛亂並護送周襄王復位後，襄王想用土地來賞賜慰勞他，晉文公推辭了，反而請求天子允許他死後能夠使用隧（即開鑿地下通道入葬）的墓葬規格。周襄王沒有答應這個請求，說道：從前我們先王擁有天下的時候，劃分出方圓千里的土地作為天子的直轄領地，用來供養天子。各國諸侯的地位與爵位，都有著嚴格的等級差別。按照先王制定的禮法，活著的時候要有顯著的德行，死後要有光明的名聲，而隧這種葬制，是隻有天子才能享用的特有禮儀。叔父您雖然對王室有著巨大的功勞，但依然不能僭越天子的禮制。於是，晉文公只好接受了土地的賞賜返回了晉國。","analysis":"【訓詁與名物】：「定襄王於郟」指晉文公出兵平定了王子帶的叛亂，迎接周襄王回到國都郟。「勞」指慰勞、賞賜。「辭」指推辭。「隧」指古代天子陵墓的一種規制，即從地面開鑿斜坡通道直達墓室，諸侯只能用垂直的墓穴（羨）。「規方千里」指劃定方圓千里的範圍。「甸服」指天子直轄的地區。「等差」指等級的差別。「叔父」是周天子對同姓大國諸侯（晉為姬姓）的尊稱。「踰」同逾，超越、僭越。\\\\n\\\\n【章法與結構】：此段圍繞「請隧」與「不許」展開。晉文公挾平叛大功，欲求非分之禮（隧）；而周襄王的拒絕則充滿了政治智慧，他引經據典，從先王劃定天下等級（甸服、等差）的總體制度講起，點出「隧」乃天子專屬之禮的定性，最後以「大功不可踰禮」作為結論。既肯定了晉文公的功勞（叔父、大功），又堅定地維護了王室的底線。晉文公最終「受地而還」，為這場禮制交鋒畫上了句號。\\\\n\\\\n【思想與義理】：這是一個極具象徵意義的歷史事件。晉文公的「請隧」，看似只是一個葬禮規格的請求，實質上是對周天子最高權威與禮樂制度的試探與挑戰。周襄王雖然在政治與軍事上已經淪落到需要依賴晉國來保住王位，但在禮法名分上，他依然堅守著「天子」的最後尊嚴。他用「禮」的不可僭越性（未可踰天子之禮），成功地擋住了霸主的政治野心。這生動地反映了春秋時代「霸權」與「王權」、「實力」與「名分」之間複雜而微妙的博弈。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-7","chapterId":"guo-yu_ch-2","order":7,"canonicalText":"王至自鄭，以陽樊賜晉文公。陽人不服，晉侯圍之。倉葛呼曰：「王以晉君為能德，故勞之以陽樊，陽樊，溫之苗裔也，敬天子之命，固不敢叛。然晉君以兵臨之，是失德也。」文公聞之，乃寬其民，陽人乃降。","sentenceIds":["guo-yu_ch-2_p-7_s-1","guo-yu_ch-2_p-7_s-2","guo-yu_ch-2_p-7_s-3","guo-yu_ch-2_p-7_s-4","guo-yu_ch-2_p-7_s-5"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周襄王從鄭國回到國都後，把陽樊這塊土地賞賜給了晉文公。陽樊的百姓不願意臣服，晉文公便派兵包圍了陽樊。陽樊大夫倉葛大聲呼喊道：天子認為晉君有高尚的道德，所以才把陽樊賞賜給您作為慰勞，我們陽樊人是溫國的後代，向來敬重天子的命令，本來是絕對不敢叛亂的。然而，晉君您現在卻用軍隊來威逼我們，這完全是喪失了天子所期盼的德行啊。晉文公聽到這番話後，便放寬了對當地百姓的軍事壓迫與政策，陽樊人於是就歸順了。","analysis":"【訓詁與名物】：「陽樊」周朝畿內的邑名。「勞」指慰勞。「苗裔」指後代子孫。「溫」古國名，陽樊人自稱為溫的後裔，強調自己是王臣。「兵」指軍隊、武力。「失德」指喪失了道德與恩德。「寬其民」指放寬政策，撤除軍事威逼。「降」指歸順、投降。\\\\n\\\\n【章法與結構】：本段敘事簡潔明快。首先交代衝突的起因：王賜陽樊而陽人不服，晉侯欲以武力解決（圍之）。情節的轉折點在於倉葛的「呼曰」：他先用「天子之命」和「溫之苗裔」表明陽樊人不願背叛的立場，然後直接指出晉文公「以兵臨之」是「失德」，這是一種極具威懾力的道德指控。最後，晉文公聽勸並「寬其民」，陽人歸順，矛盾得以圓滿解決。\\\\n\\\\n【思想與義理】：此段故事展現了「德治」與「霸道」的交鋒，以及晉文公作為霸主從善如流的政治智慧。陽樊人抗拒晉國，本質上是對王室土地被隨意割讓的不滿與對外來強權的恐懼。倉葛敏銳地抓住了晉文公自詡為「尊王」與「有德」的心理，用道德名義迫使晉軍放棄屠殺。晉文公的「寬其民」不僅化解了軍事衝突，更在天下諸侯面前保全了他「有德」的霸主形象。這說明在春秋時期，「德」不僅是道德要求，更是極具實用價值的政治策略。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-8","chapterId":"guo-yu_ch-2","order":8,"canonicalText":"溫之會，晉人執衛成公歸之於周。晉侯請殺之，王曰：「不可。夫政自上下者也，上作政，而下行之不悖，政乃成。今衛侯雖有罪，其本君也。諸侯專殺同姓之君，是蔑王法也。」晉侯乃不敢殺。","sentenceIds":["guo-yu_ch-2_p-8_s-1","guo-yu_ch-2_p-8_s-2","guo-yu_ch-2_p-8_s-3","guo-yu_ch-2_p-8_s-4","guo-yu_ch-2_p-8_s-5","guo-yu_ch-2_p-8_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在溫地舉行的諸侯會盟上，晉國人抓捕了衛成公，並把他押送到周天子那裡。晉文公請求周天子殺掉衛成公，周王說道：這不可以。政治制度與權力從來都是自上而下推行的，處於上位的天子制定政令，處於下位的諸侯執行而不敢違背，國家的政令才能算作真正確立。如今衛侯雖然犯了罪，但他畢竟是一國的君主。如果諸侯可以擅自殺害同為姬姓的國君，這就是在蔑視天子的王法啊。晉文公聽了之後，便不敢殺衛成公了。","analysis":"【訓詁與名物】：「溫之會」指公元前632年晉文公在溫地召集的諸侯會盟。「執」指抓捕。「衛成公」衛國國君，因曾與晉國有怨而被捕。「歸」指押送交給。「上」指周天子。「下」指諸侯。「悖」指違背。「本君」指一國原本的君主。「專殺」指擅自殺害。「同姓」指周王室與晉國、衛國同為姬姓。「蔑」指蔑視。\\\\n\\\\n【章法與結構】：本段的核心在於周天子拒絕晉文公「請殺」請求的說理過程。周王先提出「政自上下」的政治總綱領；然後將這一綱領應用到具體事件上，指出衛侯雖然有罪，但其「君」的身份不容抹殺；最後點出「諸侯專殺同姓之君」的實質是「蔑王法」。邏輯嚴密，不容辯駁，最終迫使強勢的晉文公「不敢殺」。\\\\n\\\\n【思想與義理】：這段記載深刻反映了西周宗法分封制下「禮法」的殘餘威嚴與「王權」的象徵意義。晉文公作為霸主，雖然有實力抓捕並處死衛成公，但他依然需要披著「尊王」的外衣，將人交給天子並「請殺」。而周天子則緊緊抓住「政自上下」的最高解釋權，以「同姓之君」和「王法」為盾牌，保住了衛成公的命。這表明，即使在王權衰落的春秋時代，「君君臣臣」的政治倫理底線依然是霸主們不敢輕易踏破的紅線。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-9","chapterId":"guo-yu_ch-2","order":9,"canonicalText":"二十四年，秦師將襲鄭，過周北門。左右皆免冑而下拜，超乘者三百乘。王孫滿觀之，言於王曰：「秦師輕而無禮，必敗。夫輕則寡謀，無禮則脫，入險而無謀，能無敗乎？秦師必敗於殽。」果如其言，秦師敗於殽。","sentenceIds":["guo-yu_ch-2_p-9_s-1","guo-yu_ch-2_p-9_s-2","guo-yu_ch-2_p-9_s-3","guo-yu_ch-2_p-9_s-4","guo-yu_ch-2_p-9_s-5","guo-yu_ch-2_p-9_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周襄王二十四年，秦穆公派遣孟明視、西乞術、白乙丙率領秦國大軍企圖長途奔襲滅亡鄭國，行軍經過周王室洛邑京師的北門。戰車上的秦軍將士雖然脫下頭盔跳下戰車向天子城門致敬，但緊接著竟然有三百輛戰車的士兵隨意施展跳躍技巧飛身躍上戰車嬉鬧（超乘者三百乘）！當時年幼的王孫滿在城頭觀察到這一幕，立刻向周襄王稟報說：秦國軍隊舉止輕浮浮躁而且毫無禮法紀律（秦師輕而無禮），這次遠徵必定會慘遭大敗！大凡部隊輕浮躁動就必定缺乏深謀遠慮，部隊毫無禮法軍紀就必定鬆懈疏漏；深入崇山峻嶺險隘重地而毫無智謀戒備，又怎麼可能不打敗仗呢？秦軍此行必定會在殽山險隘慘遭全軍覆沒！事情的發展果然正如王孫滿所預言的那樣，秦軍在回師途中於殽山峽谷遭到晉軍伏擊，全軍覆沒，三位主帥全部被俘！","analysis":"【題解與王孫滿論秦師過周北門輕而無禮必敗於殽】本段為中國古代軍事心理學與微表情觀察之千古名篇——少年王孫滿從秦軍「超乘嬉鬧、輕浮無禮」的微小行軍舉止，精準預言秦軍殽之戰必遭全軍覆沒！\\\\n【詞義訓詁】「超乘」：跳躍敏捷飛登戰車以炫技；「輕而無禮」：輕浮躁動、目無紀律；「殽之戰」：公元前627年晉秦殽之戰，晉軍全殲秦軍。\\\\n【軍隊紀律與戰略心理學】真正能打硬仗的雄師必定嚴肅整飭、深沉內斂；輕狂浮躁、炫耀技巧的部隊，在極端複雜地形中必因鬆懈大意遭致毀滅性打擊。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-10","chapterId":"guo-yu_ch-2","order":10,"canonicalText":"晉侯使隨會聘於周，定王享之餚烝，原公相禮。範子私於原公，曰：「吾聞王室之禮無毀折，今此何禮也？」原公以告王。","sentenceIds":["guo-yu_ch-2_p-10_s-1","guo-yu_ch-2_p-10_s-2","guo-yu_ch-2_p-10_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"晉侯派隨會（即士季、範武子）前往周王室進行外交聘問，周定王用餚烝（即將牲肉切碎折斷後進獻）的宴饗之禮來招待他，由原公擔任輔助行禮的儐相。隨會私下裡對原公說：我聽說周王室的最高祭祀與宴饗禮儀，牲肉都是保持完整的，不應該被切割折斷的，今天這到底是什麼禮節呢？原公把隨會的疑問報告給了周定王。","analysis":"【訓詁與名物】：「隨會」即晉國大夫士季，又稱範武子、範子。「聘」指諸侯派大夫去朝問天子或別國。「定王」指周定王。「享」指設宴款待。「餚烝」古代宴饗禮儀之一，烝指把牲肉放在俎（案板）上，餚烝是指將帶骨的肉折斷、切塊後進獻。「相禮」指在典禮中贊禮、引導。「私於」指私下對某人說。「毀折」指將牲肉切割、折斷。\\\\n\\\\n【章法與結構】：這是一個典型的「因事生問」的敘事結構。文章首先交代了事件的背景（隨會聘周，定王享之餚烝），然後通過隨會的「私問」（吾聞王室之禮無毀折，今此何禮也），拋出了一個關於禮制規範的疑問。最後以原公「告王」作為過渡，自然地引出了下文周定王對禮制的分級解釋。行文簡潔，懸念頓生。\\\\n\\\\n【思想與義理】：隨會的疑問並非無的放矢，而是反映了春秋時期各國大夫對周朝傳統禮樂制度的關注與敏感。在古人眼中，宴會上的牲肉是完整（全烝）還是切碎（餚烝），不僅僅是飲食習慣的不同，更是身份等級與外交規格的嚴格體現。隨會質疑「無毀折」，是以天子祭祀與最高規格朝會的標準來衡量這次宴饗，他誤以為周王室失禮或是輕視晉國。這揭示了禮儀在當時政治交往中作為「無聲語言」的極端重要性。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-11","chapterId":"guo-yu_ch-2","order":11,"canonicalText":"王召士季，曰：「子弗聞乎，禘郊之事，則有全烝；王公立飫，則有房烝；親戚宴饗，則有餚烝。今女晉，吾之親戚也，故享子以餚烝，以合好也。」","sentenceIds":["guo-yu_ch-2_p-11_s-1","guo-yu_ch-2_p-11_s-2","guo-yu_ch-2_p-11_s-3","guo-yu_ch-2_p-11_s-4","guo-yu_ch-2_p-11_s-5"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周定王召見士季（隨會），對他說道：您難道沒有聽說過嗎？舉行禘祭和郊祭等最隆重的祭天祀祖大典時，進獻的牲畜必須是完整的（全烝）；天子與王公諸侯站著舉行嚴肅的朝會宴飲時，進獻的是半體的牲肉（房烝）；而招待同宗親戚舉行較為輕鬆的宴飲時，進獻的才是切碎帶骨的肉（餚烝）。如今你們晉國，是我們姬姓的同宗親戚，所以我才用餚烝的禮儀來款待您，這是為了表示我們宗族之間親密和睦的關係啊。","analysis":"【訓詁與名物】：「士季」即隨會。「禘郊」指古代最隆重的祭祀，禘是祭祖宗，郊是祭天地。「全烝」指將整隻牲畜煮熟後完整地放在俎上進獻。「王公立飫（yù）」指天子與諸侯在朝堂上站立進行的嚴肅宴飲，不設座位，以示恭敬。「房烝」指將牲畜的半體肉（或分解為大塊）放在俎上。「親戚」此處特指同姓的宗族諸侯（周王與晉國同為姬姓）。「宴饗」指坐著喝酒吃飯的歡樂宴席。「餚烝」指將帶骨的肉切碎以便於食用。「合好」指結合恩情、表示親近。\\\\n\\\\n【章法與結構】：本段是周定王對隨會質疑的正面解答。定王採用了嚴密的分類排比手法，將周朝的飲食禮儀分為三個等級：「禘郊之事（全烝）」、「王公立飫（房烝）」與「親戚宴饗（餚烝）」。然後他將晉國使者的到訪精準地定位在「親戚宴饗」這一層級上，從而得出「享子以餚烝」是為了「合好」的結論。說理清晰，有理有據，完美地化解了外交誤會。\\\\n\\\\n【思想與義理】：這段話詳盡地展示了周代禮樂制度中極其精細的等級觀念與分類體系。禮儀的級別與對象的身份、場合的嚴肅程度嚴格對應：對神明（全烝）最為敬畏；對政治同僚（房烝）保持肅穆；對同宗親屬（餚烝）則強調親切與實用（切碎便於食用）。周定王巧妙地用「親戚合好」的宗法溫情，解釋了表面上看似「降級」（餚烝相對於全烝）的禮遇，這不僅維護了周禮的尊嚴，也拉近了王室與霸主晉國的關係，展現了高超的外交辭令。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-12","chapterId":"guo-yu_ch-2","order":12,"canonicalText":"「夫王公諸侯之有飫也，將以講事成章，建大德、昭大物也，故立成禮烝而已。飫以顯物，宴以合好，各有其道，不可亂也。」","sentenceIds":["guo-yu_ch-2_p-12_s-1","guo-yu_ch-2_p-12_s-2","guo-yu_ch-2_p-12_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"天子和王公諸侯之間之所以要舉行立飫（站立式的宴會），是為了在會上講習國家大事並形成法度文章，從而建立偉大的德行、彰顯重大的法規與事物，所以只需要站立著完成進獻整塊肉的禮儀就可以了。飫禮是用來彰顯國家的法度與制度的，而宴禮則是用來聯絡感情、使宗族和睦親近的，它們各自有著不同的道理與功能，是絕對不可以混淆的。","analysis":"【訓詁與名物】：「飫（yù）」古代天子與諸侯在朝堂上舉行的站立式宴會，氣氛嚴肅。「講事成章」指講習政事，使之成為有條理的法規。「建大德」指建立宏大的道德規範。「昭大物」指彰顯重大的法制與事物（如等級、名分）。「立成禮」指站立著完成禮儀。「顯物」指彰顯國家的法度與制度。「合好」指聯絡感情、和睦親族。\\\\n\\\\n【章法與結構】：這是周定王對上文禮儀解釋的理論昇華。他先對「立飫」的政治功能進行了深入剖析，指出其目的是「講事成章、建大德、昭大物」，解釋了為何這種禮儀必須保持嚴肅（立成禮烝）；然後用一個高度凝練的對仗句「飫以顯物，宴以合好」進行了對比總結，最後以「各有其道，不可亂也」作為結論，擲地有聲。\\\\n\\\\n【思想與義理】：此段論述觸及了周代禮樂制度的哲學本質——「禮以體政」。古人將看似普通的喫喝宴飲，賦予了極為深刻的政治與倫理內涵。嚴肅的「飫」代表了國家的法度、等級與威嚴（顯物），它維繫的是政治秩序；而輕鬆的「宴」代表了血緣的溫情、宗族的團結（合好），它維繫的是倫理秩序。兩者「各有其道」，相輔相成，共同構建了中國古代早期的國家治理體系。定王強調「不可亂」，正是為了捍衛這種秩序的神聖性。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-13","chapterId":"guo-yu_ch-2","order":13,"canonicalText":"武子遂不敢對而退。歸乃講聚三代之典禮，於是乎修執秩以為晉法。晉國由是修明。","sentenceIds":["guo-yu_ch-2_p-13_s-1","guo-yu_ch-2_p-13_s-2","guo-yu_ch-2_p-13_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"範武子（隨會）聽了周定王的話後，便不敢再多言，恭敬地退了下去。他回到晉國之後，便開始講習並匯聚夏、商、週三代的典章禮儀，並在此基礎上修訂了名為執秩的官員法規，將其作為晉國的國家法令。晉國的政治也因此而變得清明、有條理。","analysis":"【訓詁與名物】：「武子」即範武子，晉國大夫隨會（士季）。「對」指對答、反駁。「講聚」指講習並收集匯聚。「三代」指夏、商、週三個朝代。「執秩」是晉國法規的名稱，秩指秩序、官秩，執秩意為掌管法度秩序。「修明」指政治清明、法度修繕完備。\\\\n\\\\n【章法與結構】：這段話是前文「定王論禮」的後續與高潮。敘事分為三步：首先是武子的反應（不敢對而退），體現了他對周王禮樂智慧的折服；其次是他的行動（講聚典禮、修執秩），將個人的反思轉化為國家的立法；最後是客觀的歷史評價（晉國由是修明），點出了這場外交對話帶來的深遠影響。語言簡練，因果關係清晰。\\\\n\\\\n【思想與義理】：此段故事生動地反映了「禮法合一」的政治實踐。範武子在周王室的宴席上受到的禮儀教育，並沒有停留在表面的羞愧，而是引發了他對國家治理的深刻反思。他將周朝傳統的「典禮」轉化為晉國成文的法規（執秩），用禮儀的精神來規範官員的秩序。這說明在春秋時期，法治的思想正在萌芽，而早期的「法」正是從傳統的「禮」中脫胎而來的。懂得反省與學習的晉國，因此得以繼續保持霸業的強盛。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-14","chapterId":"guo-yu_ch-2","order":14,"canonicalText":"定王使單襄公聘於宋。遂假道於陳，以聘於楚。火朝覿矣，道茀不可行，候不在疆，司空不視途，澤不陂，川不梁，野有庾積，而民有飢色。單子見之，深知陳之必亡。","sentenceIds":["guo-yu_ch-2_p-14_s-1","guo-yu_ch-2_p-14_s-2","guo-yu_ch-2_p-14_s-3","guo-yu_ch-2_p-14_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周定王派單襄公前往宋國進行外交聘問。單襄公完成任務後，便向陳國借道，以便繼續前往楚國聘問。當時天上的大火星已經在早晨顯現了（標誌著即將進入寒冬），可是陳國的道路卻長滿了雜草無法通行，邊境上沒有負責迎接客人的候人，主管工程的司空也不去巡視道路，湖澤沒有修築堤壩，河流上也沒有架設橋樑，田野裡雖然堆積著露天的穀物，但百姓們卻面帶飢色。單襄公看到這些情況後，心裡深刻地意識到陳國必定會滅亡。","analysis":"【訓詁與名物】：「單襄公」周朝的大夫。「假道」指借路。「火朝覿（dí）」大火星（心宿二）在早晨顯現，在古代曆法中代表秋末初冬時節，覿同見。「茀（fú）」指雜草叢生，阻塞道路。「候」指古代在邊境迎送賓客的官員。「司空」主管土木工程的官員。「陂（bēi）」作動詞，修築堤壩。「梁」作動詞，架橋。「庾（yǔ）積」指露天堆放的穀物。\\\\n\\\\n【章法與結構】：本段敘事如同一幅衰敗的社會全景圖。開頭交代出行的背景（聘宋、假道陳）；中間部分是單襄公在陳國的「所見」，用了一連串緊湊的否定句與對比句（道茀、候不在、司空不視、澤不陂、川不梁、野有庾積而民飢），從交通、外交、水利到民生，全方位勾勒出陳國百廢待興的慘狀；結尾點出單襄公的「所思」（深知陳必亡），由表及裡，發人深省。\\\\n\\\\n【思想與義理】：這是一段經典的通過微觀社會現象洞察宏觀政治命運的記載。古人認為，一個國家的興衰，會通過具體的行政細節與民生狀況反映出來。陳國在即將進入寒冬之際，道路不通、水利失修、官員失職，這表明其國家機器已經癱瘓；更致命的是「野有庾積，而民有飢色」，說明統治階級橫徵暴斂，導致糧食分配極度不公，百姓陷入絕境。這種內政的極度腐敗與民心的喪失，是單襄公斷言陳國「必亡」的根本邏輯。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-15","chapterId":"guo-yu_ch-2","order":15,"canonicalText":"單子歸，告王曰：「陳侯不有大咎，國必亡。」王曰：「何故？」對曰：「夫辰角見而雨畢，天根見而水涸，本見而草木節解，駟見而隕霜，火見而清風戒寒。此先王之教民以時也。今陳侯荒怠不恤，必亡。」","sentenceIds":["guo-yu_ch-2_p-15_s-1","guo-yu_ch-2_p-15_s-2","guo-yu_ch-2_p-15_s-3","guo-yu_ch-2_p-15_s-4","guo-yu_ch-2_p-15_s-5","guo-yu_ch-2_p-15_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"單襄公回到周朝後，報告周定王說：陳國國君如果不是遭遇巨大的災禍，陳國就必定會滅亡。定王問道：這是什麼緣故呢？單襄公回答說：角宿星出現時就意味著雨季結束了，天根星出現時河流就會乾涸，氐宿星（本）出現時草木的枝節就會脫落，房宿星（駟）出現時就會降下嚴霜，大火星（心宿二）出現時淒清的寒風就在警告人們寒冬將至。這些都是古代先王用來教導百姓順應農時的自然規律。如今陳侯卻荒淫怠惰，不體恤民情、不順應天時，因此他必定會滅亡。","analysis":"【訓詁與名物】：「大咎」指大災禍。「辰角」、「天根」、「本（氐）」、「駟（房）」、「火（心）」皆為中國古代星象學中東方蒼龍七宿中的星宿名稱。「見」指在黎明時分從東方升起（晨見）。「涸」指乾涸。「節解」指草木乾枯、枝節脫落。「隕霜」指降霜。「清風戒寒」指涼風起而警告寒冬將至。「恤」指體恤、顧念。\\\\n\\\\n【章法與結構】：本段是單襄公對陳國「必亡」預言的第一層論證：違背天時。他首先引述了古代觀星授時的五個自然規律，構成了一組氣勢連貫的排比句（……見而……），展現了古人精密的曆法知識與自然秩序；然後以此為參照，點出這些自然現象背後的政治意義（先王教民以時）；最後筆鋒一轉，將陳侯的「荒怠不恤」與先王的順應天時形成強烈對比，從而得出「必亡」的結論。\\\\n\\\\n【思想與義理】：這段話反映了中國古代「天人合一」與「順天應時」的政治哲學。在傳統農業社會，天命不僅是神祕的力量，更是具體的自然規律（星象、節氣）。國君作為天下的主宰，其首要職責就是觀測天象、指導百姓按農時進行生產與準備（教民以時）。陳國在「火見」之時卻毫無防寒與過冬的準備（如前文的道茀、無梁），這說明陳侯已經徹底放棄了作為國君最基本的政治責任。這種違背自然與社會規律的荒怠，必然導致國家的覆滅。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-16","chapterId":"guo-yu_ch-2","order":16,"canonicalText":"「《周制》有之曰：『列樹以表道，立鄙食以守路，國有郊牧，疆有寓望，藪有圃草，囿有林池，所以備水旱也。』今陳國廢其政，道路不通，水旱無備，何以能久？」","sentenceIds":["guo-yu_ch-2_p-16_s-1","guo-yu_ch-2_p-16_s-2","guo-yu_ch-2_p-16_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"《周制》上有這樣的規定：在道路兩旁種植樹木來作為標誌，在邊境設立提供飲食的客舍來接待路過的人，國都外圍要有放牧的郊野，邊境上要有供賓客住宿與遠望的館舍，沼澤地裡要有茂盛的水草，園囿中要有樹林和池塘，這些都是用來防備水災和旱災的物資儲備。如今陳國廢棄了這些政令與設施，道路阻塞不通，對水旱災荒也毫無防備，這個國家怎麼能長久存在呢？","analysis":"【訓詁與名物】：「《周制》」指周朝的典章制度。「表道」指作為道路的標誌。「鄙食」指設在邊邑的客舍，提供飲食。「郊牧」指國都外圍供放牧的地方。「寓望」指供賓客住宿並便於登高遠望的館舍，寓指寄宿。「藪（sǒu）」指積水的沼澤地。「圃草」指茂盛的草本植物。「囿」指古代帝王或貴族蓄養禽獸的園林。「林池」指樹林和池塘。\\\\n\\\\n【章法與結構】：這是單襄公論證陳國「必亡」的第二層：廢棄政令和基礎設施。他同樣採取了先引經據典、後對比現實的說理結構。他一口氣列舉了《周制》中關於交通、外交接待以及自然資源保護的六項具體規定（列樹、鄙食、郊牧、寓望、藪圃、囿林），展現了一幅理想的國家治理圖景。然後將其與陳國的現狀（廢其政、道路不通、水旱無備）進行強烈對比，以一個反問句「何以能久」有力地結束論證。\\\\n\\\\n【思想與義理】：這段論述揭示了古代國家治理的微觀層面。周朝的制度不僅僅是抽象的禮樂，更包含了極為具體的公共設施建設與生態資源管理。種樹標道、建館待客是為了國家交通與外交的順暢；而保護郊牧、藪圃、林池，則是為了涵養自然資源，以備不時之需（備水旱）。陳國對這些基礎建設的全面廢棄，反映了其政府行政機能的徹底癱瘓。一個無法提供基本公共服務、無法應對自然災害的國家，自然無法長久立足。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-17","chapterId":"guo-yu_ch-2","order":17,"canonicalText":"「周之《秩官》有之曰：『敵國賓至，關尹以告，行理以節逆之，候人為導，卿出郊勞，門尹除門，宗祝薦禮。』今陳國無賓禮，是棄交也。棄交無援，亡之道也。」","sentenceIds":["guo-yu_ch-2_p-17_s-1","guo-yu_ch-2_p-17_s-2","guo-yu_ch-2_p-17_s-3","guo-yu_ch-2_p-17_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周朝的《秩官》制度上有這樣的規定：當地位對等的諸侯國賓客到來時，守關的長官要向上報告，主管外交的官員要拿著符節去迎接，候人要在前面做嚮導，卿大夫要到國都郊外去慰勞，守門的官員要清掃城門，宗祝等祭祀官員要在太廟裡準備迎接的禮儀。如今陳國完全沒有接待賓客的禮節，這就等於是拋棄了與其他國家的外交關係。拋棄了外交關係就會陷入孤立無援的境地，這就是自取滅亡的道路啊。","analysis":"【訓詁與名物】：「《秩官》」指周朝記載官吏職責與秩序的典籍。「敵國」指地位相等、匹敵的諸侯國。「關尹」把守關隘的官員。「行（háng）理」主管外交與接待賓客的官員。「節」即符節，外交憑證。「逆」指迎接。「候人」在邊境迎送賓客的官員。「除門」指打掃城門，以示尊重。「宗祝」主管宗廟祭祀與祈禱的官員。「棄交」指放棄外交往來。\\\\n\\\\n【章法與結構】：這是單襄公論證陳國「必亡」的第三層：廢棄外交禮儀。結構與前兩段如出一轍。他詳細羅列了周制中接待「敵國賓至」的七道嚴格程序（關尹告、行理逆、候人導、卿郊勞、門尹除、宗祝薦），體現了周朝外交禮儀的嚴謹與隆重。隨後一針見血地指出陳國「無賓禮」的現狀，並通過邏輯推理得出「無賓禮→棄交→無援→亡之道」的必然鏈條，結論無可辯駁。\\\\n\\\\n【思想與義理】：這段話強調了「外交禮儀」在春秋列國生存博弈中的極端重要性。在那個兼併戰爭頻發的時代，諸侯國之間的「交」不僅僅是迎來送往的面子工程，更是維繫國家安全、結成政治同盟的實質手段。陳國連最基本的賓客之禮都荒廢了（如單襄公假道而無候人），這不僅是傲慢，更是政治上的極度短視。主動切斷與外界的友好聯繫，在弱肉強食的國際環境中，無異於自絕後路。單襄公的這番分析，展現了高超的外交與戰略眼光。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-18","chapterId":"guo-yu_ch-2","order":18,"canonicalText":"「先王之令有之曰：『天道賞善而罰淫，故凡我造國，無從非彝，無即慆淫，各守爾典，以承天休。』今陳侯淫亂於夏氏，棄其國典，是速其禍也。」","sentenceIds":["guo-yu_ch-2_p-18_s-1","guo-yu_ch-2_p-18_s-2","guo-yu_ch-2_p-18_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"先王的教令中曾這樣說過：天道的規律是獎賞善良而懲罰邪惡淫亂，所以凡是我們建立的諸侯國，都不要去遵從那些不合乎常規法度的行為，不要去親近過度逸樂與荒淫的事情，各自堅守你們國家的典章制度，以此來承受上天賜予的福祐。如今陳侯卻與夏氏的女眷發生淫亂的關係，完全拋棄了國家的法典，這簡直就是在加速災禍的降臨啊。","analysis":"【訓詁與名物】：「淫」指過度、邪惡、淫亂。「造國」指建立諸侯國。「無」同毋，不要。「非彝」指不符合常規法度的行為，彝指常道、法度。「即」指親近、靠近。「慆（tāo）淫」指過度沉溺於逸樂與荒淫。「典」指典章制度。「休」指福氣、福祐。「夏氏」指陳國大夫夏徵舒的母親夏姬，陳靈公與其私通。「速」指加速、招致。\\\\n\\\\n【章法與結構】：這是單襄公論證陳國「必亡」的第四層，也是最核心的道德與政治指控。他依然採用「先王之令」與「陳侯現狀」對比的模式。先引出先王的「天道賞罰」觀與「守典承休」的政治規矩；然後直指陳靈公的致命敗筆——「淫亂夏氏」，這是一種極其嚴重的道德敗壞與政治失範（棄國典）。最後以「速其禍」作結，推斷出陳國即將迎來毀滅。\\\\n\\\\n【思想與義理】：此段論述將國家的興衰直接與君主的道德作風掛鉤。在中國傳統的「天命觀」中，天意並非盲目，而是「賞善罰淫」的道德裁判者。陳靈公作為一國之君，本應是道德的表率與法律的維護者，卻帶頭與臣子的母親（夏姬）私通，這不僅是個人私德的淪喪，更是對整個國家倫理秩序與法典（國典）的公然踐踏。這種統治階級頂層的腐朽與淫亂，必然會招致上天的懲罰（即隨後夏徵舒的弒君叛亂）。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-19","chapterId":"guo-yu_ch-2","order":19,"canonicalText":"「昔先王之教，懋帥其德也，猶恐殞越。若廢其教而棄其制，蔑其官而犯其令，將何以守國？居大國之間，而無政無德，陳必滅矣。」","sentenceIds":["guo-yu_ch-2_p-19_s-1","guo-yu_ch-2_p-19_s-2","guo-yu_ch-2_p-19_s-3","guo-yu_ch-2_p-19_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當年古代先王推行道德教化之際，尚且勉勵引導自己竭盡全力弘揚崇高德行，時刻戰戰兢兢唯恐出現顛覆失足（猶恐殞越）！如今陳國竟然徹底廢棄了先王的教化、拋棄了國家的制度，蔑視各級官員的職守、公然違犯各項政令法令，又憑藉什麼能夠守護保全國家社稷呢？身處在晉國與楚國兩大強國夾縫之間，自身內部既沒有修明的政令，又沒有深厚的道德民心，陳國必定徹底滅亡無疑了！","analysis":"【題解與背景】\\\\n本段選自《國語》〈周語中〉第 48 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「昔先王之教懋帥其德也猶恐殞越若廢其教而棄……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「昔」、「先」、「王」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《國語》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：guo-yu_ch-2_p-19）。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-20","chapterId":"guo-yu_ch-2","order":20,"canonicalText":"六年，單子如楚。八年，陳侯殺於夏氏。九年，楚子入陳。單襄公之言皆驗。","sentenceIds":["guo-yu_ch-2_p-20_s-1","guo-yu_ch-2_p-20_s-2","guo-yu_ch-2_p-20_s-3","guo-yu_ch-2_p-20_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"到了周定王六年的時候，單襄公前往楚國。到了定王八年的時候，陳國國君（陳靈公）在夏氏家中被殺。到了定王九年的時候，楚國國君（楚莊王）率軍攻入陳國。單襄公當初所說的預言全部都應驗了。","analysis":"【訓詁與名物】：「如」指前往。「陳侯殺於夏氏」指陳靈公與夏姬私通，被夏姬的兒子夏徵舒射殺。「楚子」即楚莊王，當時楚國國君自稱為王，但周王室只承認其子爵地位，故稱楚子。「入陳」指楚莊王以討伐夏徵舒弒君為名，率軍攻入陳國並一度將其吞併。「驗」指應驗。\\\\n\\\\n【章法與結構】：這是一段經典的史家客觀記事。沒有長篇大論的說教，僅用極其精煉的編年體筆法，列出了三個關鍵年份（六年、八年、九年）發生的三個歷史事件（如楚、殺陳侯、入陳）。這三個事件構成了一條完整的因果鏈條，精準地對應了前文單襄公對陳國「必亡」的種種分析，最後以「皆驗」二字收束，具有極強的歷史說服力。\\\\n\\\\n【思想與義理】：這段史實的應驗，印證了單襄公卓越的政治洞察力，也再次重申了傳統史學中「多行不義必自斃」的歷史規律。陳靈公的荒淫無道、內政廢弛與外交失策，最終引發了內亂（被殺）與外患（楚國入侵）。這告訴後人，一個國家的滅亡往往是從內部的腐敗與失德開始的。歷史的發展並非偶然，而是遵循著嚴密的道德與政治邏輯。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-21","chapterId":"guo-yu_ch-2","order":21,"canonicalText":"定王八年，使劉康公聘於魯，發幣於大夫。季文子、孟獻子皆儉，叔孫宣子、東門子家皆侈。","sentenceIds":["guo-yu_ch-2_p-21_s-1","guo-yu_ch-2_p-21_s-2"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周定王八年，派大夫劉康公前往魯國進行外交聘問，並向魯國的大夫們分發賞賜的禮物。在接受禮物時，季文子和孟獻子表現得都非常節儉樸素，而叔孫宣子和東門子家表現得都非常奢侈浮華。","analysis":"【訓詁與名物】：「劉康公」周朝的大夫。「聘」指諸侯間或王室與諸侯間的外交訪問。「發幣」指分發禮物或賞賜，幣在此泛指禮物如布帛、玉器等。「季文子、孟獻子、叔孫宣子、東門子家」皆為當時魯國掌握重權的卿大夫，其中前三者為魯國著名的「三桓」家族成員。「儉」指節儉、剋制。「侈」指奢侈、鋪張。\\\\n\\\\n【章法與結構】：本段敘事極其簡約，採用了鮮明的對比手法。首句交代事件背景（劉康公聘魯發幣），這是考察人物品行的特定外交場合；第二句用「皆儉」與「皆侈」將魯國的四位權臣分為兩組，形成了強烈的反差。這種白描式的人物刻畫，沒有一句評論，卻為下文劉康公的政治預言以及這幾位大夫未來的命運埋下了伏筆。\\\\n\\\\n【思想與義理】：這段記載反映了中國古代政治文化中「以儉立名，以侈取禍」的深刻道德觀。在古人看來，「儉」與「侈」不僅僅是個人生活方式的選擇，更是政治品格與政治前途的象徵。「儉」代表著克己復禮、懂得收斂與敬畏，而「侈」則意味著放縱私慾、驕傲自滿。在魯國這個傳統的「禮義之邦」，大夫們在面對王室使者賞賜時的態度，折射出了他們內心對禮法的不同態度，這也預示了他們家族日後截然不同的政治命運。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-22","chapterId":"guo-yu_ch-2","order":22,"canonicalText":"歸，王問魯大夫孰賢？對曰：「季、孟其長處魯乎！叔孫、東門其亡乎！若家不亡，身必不免。」王曰：「何故？」對曰：「夫儉，德之共也；侈，惡之大也。季、孟恭儉以安其位，叔孫、東門驕侈以肆其志。驕侈必亡，自然之數也。」","sentenceIds":["guo-yu_ch-2_p-22_s-1","guo-yu_ch-2_p-22_s-2","guo-yu_ch-2_p-22_s-3","guo-yu_ch-2_p-22_s-4","guo-yu_ch-2_p-22_s-5","guo-yu_ch-2_p-22_s-6","guo-yu_ch-2_p-22_s-7","guo-yu_ch-2_p-22_s-8","guo-yu_ch-2_p-22_s-9","guo-yu_ch-2_p-22_s-10"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"劉康公返回洛邑之後，周定王詢問他：魯國的這幾位執政大夫之中，究竟哪幾位是真正的賢能之士？劉康公回答說：季文子與孟獻子兩大家族恐怕能夠長久立足保全於魯國（長處魯乎）！而叔孫宣子與東門子家兩大家族恐怕即將走向敗亡了！縱然其宗族僥倖沒有徹底滅亡，他們自身的性命也必定在劫難逃！周定王問道：這是什麼原因呢？劉康公回答說：大凡節儉節約，是一切崇高品德共同依託的基石（儉，德之共也）；大凡驕奢淫逸，是一切罪惡敗德之中最為嚴重的罪魁（侈，惡之大也）！季文子與孟獻子為人恭敬節儉，以此安定保全自己的爵位；叔孫宣子與東門子家驕橫奢靡，以此肆意放縱自己的狂妄私慾！驕奢淫逸者必定走向滅亡，這是歷史與天道必然的客觀規律（自然之數也）！","analysis":"【題解與儉德之共侈惡之大劉康公論魯大夫興衰】本段為中國倫理哲學與家風家訓之千古名言——「儉，德之共也；侈，惡之大也（司馬光《訓儉示康》開卷首引）」！\\\\n【詞義訓詁】「長處魯」：長久在魯國安享尊榮；「儉德之共，侈惡之大」：千古名句；節儉是羣德之母，奢侈是眾惡之首；「自然之數」：不可抗拒的客觀規律。\\\\n【修身齊家與政權興衰】統治階級生活作風的節儉與奢侈，直接折射其道德操守與政治生命力。節儉者保持清醒自律、民心擁戴；奢靡者迅速腐化墮落、身死族滅。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-23","chapterId":"guo-yu_ch-2","order":23,"canonicalText":"十六年，魯宣公卒。赴者未及，東門氏來告亂，子家奔齊。簡王十一年，魯叔孫宣伯亦奔齊，成公未歿而兩家皆敗，劉子之言皆驗。","sentenceIds":["guo-yu_ch-2_p-23_s-1","guo-yu_ch-2_p-23_s-2","guo-yu_ch-2_p-23_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"到了周定王十六年的時候，魯宣公去世了。前往周朝報喪的使者還沒到達，東門氏家族的人就來報告說魯國發生了內亂，東門子家被迫逃亡到了齊國。到了周簡王十一年的時候，魯國的叔孫宣伯（即叔孫宣子）也逃亡到了齊國。魯成公還沒有去世，這兩個以奢侈著稱的家族就都已經敗落了，劉康公當初的預言全都應驗了。","analysis":"【訓詁與名物】：「十六年」指周定王十六年。「卒」指國君去世。「赴（fù）者」指前去報喪的使者，赴同訃。「東門氏」即東門子家的家族。「告亂」指報告國內發生了政治動亂。「奔」指政治逃亡。「簡王」即周簡王，定王之子。「宣伯」即叔孫宣子。「歿」指死。「劉子」指劉康公。「驗」指應驗。\\\\n\\\\n【章法與結構】：這又是一段典型的史家驗證式補敘。作者嚴格按照時間線索（定王十六年、簡王十一年），分別敘述了東門子家和叔孫宣子這兩個當初表現「侈」的大夫家族敗落逃亡的結局。通過「未及」、「告亂」、「奔齊」等動詞，營造出政治鬥爭的殘酷與突發性。最後以「兩家皆敗，劉子之言皆驗」作結，與前文的「皆侈」遙相呼應。\\\\n\\\\n【思想與義理】：這段歷史結局完美印證了儒家「驕奢必敗」的政治哲學。東門子家和叔孫宣伯當初在接受王室賞賜時表現出的奢侈與張揚，本質上是他們在魯國國內專權跋扈、失去敬畏之心的外化。這種驕狂的政治作風必然會引發激烈的權力鬥爭與他人的忌恨，最終導致他們在殘酷的政治傾軋中身敗名裂、流亡他鄉。歷史的報應雖然有遲早，但其內在的邏輯（失德必敗）卻是鐵面無私的。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-24","chapterId":"guo-yu_ch-2","order":24,"canonicalText":"簡王八年，魯成公來朝，使叔孫僑如先聘且告。見王孫說，與之語。說言於王曰：「魯叔孫之來也，必有異謀，其言甘而動傲，傲則自肆，甘則欲得於人。肆必犯令，欲必害國。叔孫必不免於難。」後果如其言。","sentenceIds":["guo-yu_ch-2_p-24_s-1","guo-yu_ch-2_p-24_s-2","guo-yu_ch-2_p-24_s-3","guo-yu_ch-2_p-24_s-4","guo-yu_ch-2_p-24_s-5","guo-yu_ch-2_p-24_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周簡王八年，魯成公前來朝見周天子，他先派大夫叔孫僑如（即叔孫宣伯）前來聘問並通報消息。叔孫僑如見到了大夫王孫說，並與他交談。王孫說隨後對周王說道：魯國叔孫這次前來，心裡必定懷有其他的圖謀，他的言辭極其甜言蜜語，但舉止卻十分傲慢。舉止傲慢就會放縱自己的行為，言辭甜美則是為了從別人那裡獲取好處。行為放縱就必然會觸犯國家的法令，貪得無厭就必然會損害國家的利益。叔孫必定無法免除災禍。後來，事情果然就像王孫說所預言的那樣發生了（叔孫僑如因圖謀不軌而被迫逃亡齊國）。","analysis":"【訓詁與名物】：「朝」指諸侯覲見天子。「叔孫僑如」即前文提到的叔孫宣子（宣伯）。「聘且告」指先進行外交訪問並通報國君即將到來。「王孫說（yuè）」周朝的大夫。「異謀」指不同尋常的、非分的圖謀。「甘」指言辭甜美、諂媚。「動傲」指舉止傲慢。「自肆」指放縱自己。「犯令」指觸犯法令。「害國」指損害國家。「免於難」指免遭災禍。\\\\n\\\\n【章法與結構】：本段敘事極為緊湊，核心在於王孫說的「觀人術」與邏輯推理。開篇交代人物與事件背景；隨後重點突出王孫說對叔孫僑如的精準評價：「言甘而動傲」；接著，王孫說展示了強大的邏輯推導能力：傲→自肆→犯令，甘→欲得→害國，最終得出「必不免於難」的結論，層層遞進，絲絲入扣。結尾一句「後果如其言」，為這段精彩的政治預言畫上句號。\\\\n\\\\n【思想與義理】：這段記載生動地展現了先秦時代政治家「聽言觀行」的識人智慧。王孫說透過叔孫僑如表面上自相矛盾的特徵（言甘與動傲），敏銳地洞察到了他內心隱藏的政治野心與性格缺陷。言辭諂媚是為了謀取私利（欲得），舉止傲慢則是權力膨脹後的無所顧忌（自肆）。一個既貪婪又放縱的權臣，必然會為了爭權奪利而踐踏法紀、損害國家，最終也必然會遭到政治的反噬。這對後世的官場與人際交往都具有極強的警示意義。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-25","chapterId":"guo-yu_ch-2","order":25,"canonicalText":"晉既克楚於鄢，使郤至告慶於周。未將事，王叔簡公飲之酒，交酬好貨皆厚，飲酒宴語相說也。","sentenceIds":["guo-yu_ch-2_p-25_s-1","guo-yu_ch-2_p-25_s-2"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"晉國在鄢陵之戰中打敗楚國之後，派遣大夫郤至到周天子那裡報捷慶祝。在郤至還沒有正式履行報捷的公事之前，周朝的大夫王叔簡公就設宴請他喝酒，兩人在宴席上互相敬酒，互贈的禮物都非常豐厚，他們一邊喝酒一邊高談闊論，彼此都聊得非常高興。","analysis":"【訓詁與名物】：「克楚於鄢」指公元前575年的鄢陵之戰，晉國大敗楚國。「郤至」晉國大夫，字溫季。「告慶」定向天子報告勝利的喜訊。「將事」指履行公事、舉行儀式。「王叔簡公」即王叔陳生，周王室的卿士。「交酬」指互相敬酒。「好貨」指美好的禮物。「說」同悅，高興。\\\\n\\\\n【章法與結構】：本段敘事輕快，為後文的政治悲劇埋下伏筆。開頭交代了郤至「告慶」的宏大背景（晉克楚），凸顯了他挾大勝之威而來的志得意滿；然後鏡頭迅速切換到「未將事」時的私宴，細緻描寫了王叔簡公與郤至之間的「交酬厚」、「相說也」。這種公事未辦先拉幫結派的行為，在重禮法的古人眼中已屬僭越，暗示了兩人的政治作風存在嚴重問題。\\\\n\\\\n【思想與義理】：這段記載折射了春秋中期王室衰微、大夫專權的政治生態。晉國打勝仗向周天子報捷，本是一場嚴肅的「尊王」公務活動。然而，代表周王室的王叔簡公與代表晉國的郤至，卻把這當成了私人結交與權力尋租的機會（交酬好貨）。這種將國家利益與外交活動私有化、娛樂化的現象，暴露了當時貴族階層在政治上的短視與道德上的墮落。兩人表面上的「相說」，實則是驕奢盲目的互相吹捧。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-26","chapterId":"guo-yu_ch-2","order":26,"canonicalText":"明日，王孫子譽諸朝，郤至見邵桓公，與之語。邵公以告單襄公曰：「王叔子譽溫季，以為必相晉國，吾見之，其言狂而自伐，若不自損，恐不免於禍。」單襄公曰：「然，吾亦察之矣。」","sentenceIds":["guo-yu_ch-2_p-26_s-1","guo-yu_ch-2_p-26_s-2","guo-yu_ch-2_p-26_s-3","guo-yu_ch-2_p-26_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"到了第二天，王孫子（即王叔簡公）在朝堂上大肆讚譽郤至。後來郤至又去拜見邵桓公，並與他交談。邵桓公事後把情況告訴單襄公說：王叔子極力讚譽溫季（郤至），認為他將來必定能擔任晉國的正卿（執政），但我見了他之後，卻發現他言辭狂妄且喜歡自我誇耀，如果他不知道自我收斂與貶損，恐怕難以免遭殺身之禍。單襄公回答說：是的，我也已經察覺到這一點了。","analysis":"【訓詁與名物】：「王孫子」即王叔簡公。「譽諸朝」指在朝堂上公開讚美。「邵桓公」周朝的大夫。「相晉國」指擔任晉國的正卿（中軍將），掌握國政。「溫季」即郤至。「狂」指狂妄自大。「自伐」指自我誇耀功勞。「自損」指自我貶損、收斂、謙虛。「察」指觀察、察覺。\\\\n\\\\n【章法與結構】：本段通過旁觀者（邵桓公與單襄公）的視角，對郤至進行了冷酷的政治「會診」。文章形成了一種絕妙的反差：一面是王叔簡公的「譽諸朝」與「必相晉國」的盲目樂觀；另一面卻是邵桓公「言狂自伐」與「不免於禍」的致命診斷。單襄公的一句「吾亦察之矣」，更是為這份死亡診斷書簽了字，懸念迭起，引人入勝。\\\\n\\\\n【思想與義理】：這段對話展現了古代智者極高的「知人論世」之明。在儒家與道家的政治哲學中，「滿招損，謙受益」是鐵律。郤至雖然有著鄢陵之戰的大功，但他「言狂自伐」，不懂得隱藏鋒芒與自我收斂（不自損）。在權力鬥爭極為殘酷的晉國政壇，這種狂妄必然會引發同僚的嫉恨與國君的猜忌。邵桓公與單襄公透過他驕狂的言辭，就已經預見了他身敗名裂的結局，這體現了傳統文化對「戒驕戒躁」的深刻認同。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-27","chapterId":"guo-yu_ch-2","order":27,"canonicalText":"「吾曰：『子則賢矣。抑晉國之舉也，不失其次，吾懼政之未及子也。』謂我曰：『夫何次之有？昔先軫、欒枝、趙衰皆以功進，何次之守？吾今有大功於鄢，晉政其舍我其誰！』此其自伐之甚也。」","sentenceIds":["guo-yu_ch-2_p-27_s-1","guo-yu_ch-2_p-27_s-2","guo-yu_ch-2_p-27_s-3","guo-yu_ch-2_p-27_s-4","guo-yu_ch-2_p-27_s-5","guo-yu_ch-2_p-27_s-6","guo-yu_ch-2_p-27_s-7"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"（單襄公繼續說道：）我曾對郤至說：您確實非常賢能。不過晉國在提拔官員時，向來是不會打亂論資排輩的次序的，我擔心晉國的正卿之位還輪不到您。他卻對我說：這有什麼次序可言呢？從前晉國的先軫、欒枝、趙衰等人，都是因為立下了大功而被提拔的，他們哪裡遵守過什麼次序？我如今在鄢陵之戰中立下了大功，晉國的執政之位如果不給我，還能給誰呢！這簡直是他自我誇耀到了極點啊。","analysis":"【訓詁與名物】：「抑」表示轉折，不過、但是。「舉」指提拔、選拔官員。「次」指論資排輩的次序、班次。「及」指輪到。「先軫、欒枝、趙衰」皆為晉文公時期的名臣，曾因功打破常規被提拔。「守」指遵守。「自伐之甚」指自我誇耀到了極點。\\\\n\\\\n【章法與結構】：本段是單襄公對郤至「自伐」的具體舉證。這是一段極其生動的情境重現。單襄公先以委婉的勸誡（子則賢矣、不失其次）來試探；而郤至的回答則是咄咄逼人、狂態畢露，他用三個反問句和感嘆句（何次之有、何次之守、舍我其誰），將自己的驕橫狂妄展現得淋漓盡致。最後單襄公的一句點評（此其自伐之甚也），為郤至的狂言定性，邏輯順暢。\\\\n\\\\n【思想與義理】：這段對話深刻揭示了郤至政治上的極度幼稚與狂妄。單襄公的「不失其次」，實際上是在提醒他晉國政治格局的複雜與規矩（晉國長期實行嚴格的六卿輪替制度）。但郤至卻被鄢陵之戰的軍功沖昏了頭腦，他盲目地引用歷史特例（先軫等人），試圖打破規則（何次之守），並發出「舍我其誰」的狂言。這種無視體制、以功邀賞、目中無人的態度，在任何時代都是官場的大忌，必然會將自己推向所有同僚的對立面。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-28","chapterId":"guo-yu_ch-2","order":28,"canonicalText":"襄公曰：「人有言曰：『兵在其頸。』其郤至之謂乎！君子不自稱也，非以讓也，惡其蓋人也。夫人性陵上者兇，蓋人者怨。今郤至矜其伐而蓋其上，是速其死也。」","sentenceIds":["guo-yu_ch-2_p-28_s-1","guo-yu_ch-2_p-28_s-2","guo-yu_ch-2_p-28_s-3","guo-yu_ch-2_p-28_s-4","guo-yu_ch-2_p-28_s-5","guo-yu_ch-2_p-28_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"單襄公接著說：俗話說：兵刃已經架在了他的脖子上。這說的大概就是郤至這樣的人吧！君子不喜歡自我稱讚，這並不是為了故意表現謙讓，而是厭惡這種行為會掩蓋別人的光芒。人的本性是這樣的：欺凌上級的必然會遭遇兇險，掩蓋別人光芒的必然會招致怨恨。如今郤至驕傲地誇耀自己的功勞，並且掩蓋了他上級與同僚的功績，這簡直就是在加速他自己的死亡啊。","analysis":"【訓詁與名物】：「兵在其頸」古諺語，指大禍臨頭、死期將至。「自稱」指自我稱讚。「讓」指謙讓。「蓋人」指掩蓋、壓倒別人的功勞與名聲。「陵上」指欺凌、冒犯上級（國君或正卿）。「凶」指兇險、災禍。「矜（jīn）」指驕傲自誇。「伐」指功勞。「速」指加速。\\\\n\\\\n【章法與結構】：這是單襄公對郤至悲劇命運的終極哲學剖析。他先引俗語「兵在其頸」發出驚心動魄的警告；然後提出核心論點：「君子不自稱，惡其蓋人」；接著進行深刻的人性論證：「陵上者兇，蓋人者怨」；最後結合郤至的具體行為（矜伐蓋上），嚴絲合縫地推導出他「速其死也」的必然結局。說理猶如老吏斷獄，字字見血。\\\\n\\\\n【思想與義理】：本段論述達到了中國古代政治心理學的極高境界。單襄公一語道破了「謙虛」的社會學本質：謙讓不是虛偽，而是一種自我保護，因為「自稱」會引發旁人的嫉妒與怨恨（蓋人者怨）。在一個權力高度集中的體制內，功高震主（陵上、蓋上）是臣子最危險的處境。郤至的悲劇在於，他不僅沒有意識到自己的功勞已經引起了別人的忌憚，反而四處炫耀，這等同於在為自己挖掘墳墓。這給後世留下了極其深刻的處世警示。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-29","chapterId":"guo-yu_ch-2","order":29,"canonicalText":"「晉之克也，天有惡於楚也，故儆之以晉。而郤至佻天之功以為己力，不亦難乎？佻天不祥，乘人不義，不義不祥，將何以存？其死必不久矣。」","sentenceIds":["guo-yu_ch-2_p-29_s-1","guo-yu_ch-2_p-29_s-2","guo-yu_ch-2_p-29_s-3","guo-yu_ch-2_p-29_s-4","guo-yu_ch-2_p-29_s-5"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"鄢陵之戰晉國之所以能夠戰勝楚國，是因為上天厭棄楚國的暴虐無道，所以藉助晉國的軍隊力量來警示懲戒楚國！然而郤至竟然狂妄地把上天的浩瀚神功竊取據為己有當作自己的個人能耐（佻天之功以為己力），這豈不是大逆不道太糊塗了嗎？竊取天功屬於極端不祥（佻天不祥），乘人之危欺凌同僚屬於極端不義（乘人不義）；身上既背負著不義之名又招致了不祥之禍，他將來又憑什麼能夠安身立命長久存活呢？他走向滅亡死亡的日子必定不遠了！","analysis":"【題解與佻天之功以為己力單襄公論郤至必死】單襄公提出著名的「佻天之功（竊取天功）」批判——任何重大歷史勝利皆是時代大勢與天道所歸，自居全功、居功自傲者必遭天譴！\\\\n【詞義訓詁】「佻天之功」：佻，音挑，竊取；將大勢與集體勝利竊為個人戰功；「佻天不祥，乘人不義」：道德與天理之雙重破產。\\\\n【功成名就者的謙退智慧】成大功者必須深明「大功歸於大勢與眾人」，時刻保持謙卑敬畏；一旦自居其功、不可一世，必將被政治同僚與最高統治者共同清算。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-2_p-30","chapterId":"guo-yu_ch-2","order":30,"canonicalText":"郤至歸，明年死難。及伯輿之獄，王叔陳生奔晉。單襄公之言皆驗。周之史官，其知禮而明察興亡如此。","sentenceIds":["guo-yu_ch-2_p-30_s-1","guo-yu_ch-2_p-30_s-2","guo-yu_ch-2_p-30_s-3","guo-yu_ch-2_p-30_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"郤至回到晉國後，第二年就在政治動亂中被殺死了。後來到了伯輿之獄的事件時，王叔陳生（即王叔簡公）也因為爭權失敗而被迫逃亡到了晉國。單襄公當初所說的預言全部都應驗了。周朝的史官們，他們懂得禮法並且能夠敏銳地洞察國家的興亡，竟然達到了這樣神奇的地步。","analysis":"【訓詁與名物】：「明年」指第二年。「死難（nàn）」指在晉國的政治大清洗（三郤之難）中被殺。「伯輿之獄」指公元前543年，周王室大夫伯輿與王叔陳生爭奪政權的政治訴訟事件。「王叔陳生」即前文與郤至交好的王叔簡公。「奔」指政治流亡。「驗」指應驗。「知禮」指懂得傳統的禮法與道德規範。「明察興亡」指能夠清晰地預見國家與個人的興衰成敗。\\\\n\\\\n【章法與結構】：這是一段強有力的史家結語。前半部分是冷峻的編年史實記錄，短短兩句話，交代了郤至（死難）與王叔簡公（奔晉）這兩個當年「交酬好貨」之人的悲慘結局，用事實宣告了單襄公預言的「皆驗」。後半部分則是《國語》編纂者的最高讚譽（周之史官，其知禮而明察興亡如此），直接點明瞭全篇的主旨，餘音繞樑。\\\\n\\\\n【思想與義理】：這段總結將個體的悲劇上升到了對歷史規律與史官精神的禮讚。郤至與王叔簡公的覆滅，證明瞭「違禮必敗」、「驕奢必亡」並非空洞的說教，而是歷史運行的鐵律。而單襄公等周朝史官（智者）之所以能夠「明察興亡」，並不是因為他們有什麼神祕的占卜術，而是因為他們深諳「禮」的本質——即洞察人性與政治運作的底層邏輯。這體現了先秦史學「以史為鑒」、「禮治天下」的崇高歷史使命感。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"guo-yu_ch-2_p-1_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-1","order":1,"canonicalText":"襄王十三年，鄭人伐滑。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-1_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-1","order":2,"canonicalText":"王使遊孫伯請滑，鄭人執之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-1_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-1","order":3,"canonicalText":"王怒，將以狄伐鄭。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-1_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-1","order":4,"canonicalText":"富辰諫曰：「不可。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-1_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-1","order":5,"canonicalText":"古人有言曰：『兄弟鬩於牆，外禦其務。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-1_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-1","order":6,"canonicalText":"』鄭，周之伯父也，有小怨而棄之，引戎狄以伐同姓，是自拔其本也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-1_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-1","order":7,"canonicalText":"且王怒不可長，狄德不可恃，願王圖之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-1_s-8","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-1","order":8,"canonicalText":"」王不聽，遂以狄伐鄭。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-2_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-2","order":1,"canonicalText":"王德狄人，將以其女為後。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-2_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-2","order":2,"canonicalText":"富辰諫曰：「不可。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-2_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-2","order":3,"canonicalText":"夫婚姻，禍福之階也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-2_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-2","order":4,"canonicalText":"由之利內則福，利外則取禍。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-2_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-2","order":5,"canonicalText":"今王以狄女為後，狄貪而無信，必生內變。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-2_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-2","order":6,"canonicalText":"且諸侯聞之，皆謂王棄宗族而親蠻夷，其誰肯輔王？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-2_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-2","order":7,"canonicalText":"願王熟思之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-2_s-8","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-2","order":8,"canonicalText":"」王不聽，遂立狄女為後。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-3_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-3","order":1,"canonicalText":"王曰：「利何如而內，何如而外？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-3_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-3","order":2,"canonicalText":"」對曰：「尊貴、明賢、庸勛、長老、愛親、禮新、親舊。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-3_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-3","order":3,"canonicalText":"然則民莫不協，神無不享，是謂利內。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-3_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-3","order":4,"canonicalText":"今狄無是七者，而王親之，是利外也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-3_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-3","order":5,"canonicalText":"利外必亡。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-3_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-3","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-4_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-4","order":1,"canonicalText":"十八年，王黜狄後。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-4_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-4","order":2,"canonicalText":"狄人來誅殺譚伯。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-4_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-4","order":3,"canonicalText":"富辰曰：「昔吾驟諫王，王弗從，以及此難。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-4_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-4","order":4,"canonicalText":"若我不出，王其以我為懟乎！","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-4_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-4","order":5,"canonicalText":"」遂出，佐王戰，死之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-5_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-5","order":1,"canonicalText":"初，惠後欲立王子帶，故以其黨啟狄人。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-5_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-5","order":2,"canonicalText":"狄人遂入，周王乃出居於鄭，晉文公納之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-6_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-6","order":1,"canonicalText":"晉文公既定襄王於郟，王勞之以地，辭，請隧焉。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-6_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-6","order":2,"canonicalText":"王不許，曰：「昔我先王之有天下也，規方千里以為甸服，以供天子。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-6_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-6","order":3,"canonicalText":"諸侯之有位，各有等差。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-6_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-6","order":4,"canonicalText":"王者之制，生有明德，死有明名，隧者天子之禮也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-6_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-6","order":5,"canonicalText":"叔父雖有大功，未可踰天子之禮也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-6_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-6","order":6,"canonicalText":"」文公遂受地而還。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-7_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-7","order":1,"canonicalText":"王至自鄭，以陽樊賜晉文公。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-7_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-7","order":2,"canonicalText":"陽人不服，晉侯圍之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-7_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-7","order":3,"canonicalText":"倉葛呼曰：「王以晉君為能德，故勞之以陽樊，陽樊，溫之苗裔也，敬天子之命，固不敢叛。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-7_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-7","order":4,"canonicalText":"然晉君以兵臨之，是失德也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-7_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-7","order":5,"canonicalText":"」文公聞之，乃寬其民，陽人乃降。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-8_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-8","order":1,"canonicalText":"溫之會，晉人執衛成公歸之於周。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-8_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-8","order":2,"canonicalText":"晉侯請殺之，王曰：「不可。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-8_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-8","order":3,"canonicalText":"夫政自上下者也，上作政，而下行之不悖，政乃成。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-8_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-8","order":4,"canonicalText":"今衛侯雖有罪，其本君也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-8_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-8","order":5,"canonicalText":"諸侯專殺同姓之君，是蔑王法也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-8_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-8","order":6,"canonicalText":"」晉侯乃不敢殺。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-9_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-9","order":1,"canonicalText":"二十四年，秦師將襲鄭，過周北門。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-9_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-9","order":2,"canonicalText":"左右皆免冑而下拜，超乘者三百乘。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-9_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-9","order":3,"canonicalText":"王孫滿觀之，言於王曰：「秦師輕而無禮，必敗。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-9_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-9","order":4,"canonicalText":"夫輕則寡謀，無禮則脫，入險而無謀，能無敗乎？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-9_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-9","order":5,"canonicalText":"秦師必敗於殽。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-9_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-9","order":6,"canonicalText":"」果如其言，秦師敗於殽。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-10_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-10","order":1,"canonicalText":"晉侯使隨會聘於周，定王享之餚烝，原公相禮。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-10_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-10","order":2,"canonicalText":"範子私於原公，曰：「吾聞王室之禮無毀折，今此何禮也？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-10_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-10","order":3,"canonicalText":"」原公以告王。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-11_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-11","order":1,"canonicalText":"王召士季，曰：「子弗聞乎，禘郊之事，則有全烝；","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-11_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-11","order":2,"canonicalText":"王公立飫，則有房烝；","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-11_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-11","order":3,"canonicalText":"親戚宴饗，則有餚烝。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-11_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-11","order":4,"canonicalText":"今女晉，吾之親戚也，故享子以餚烝，以合好也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-11_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-11","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-12_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-12","order":1,"canonicalText":"「夫王公諸侯之有飫也，將以講事成章，建大德、昭大物也，故立成禮烝而已。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-12_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-12","order":2,"canonicalText":"飫以顯物，宴以合好，各有其道，不可亂也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-12_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-12","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-13_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-13","order":1,"canonicalText":"武子遂不敢對而退。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-13_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-13","order":2,"canonicalText":"歸乃講聚三代之典禮，於是乎修執秩以為晉法。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-13_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-13","order":3,"canonicalText":"晉國由是修明。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-14_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-14","order":1,"canonicalText":"定王使單襄公聘於宋。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-14_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-14","order":2,"canonicalText":"遂假道於陳，以聘於楚。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-14_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-14","order":3,"canonicalText":"火朝覿矣，道茀不可行，候不在疆，司空不視途，澤不陂，川不梁，野有庾積，而民有飢色。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-14_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-14","order":4,"canonicalText":"單子見之，深知陳之必亡。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-15_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-15","order":1,"canonicalText":"單子歸，告王曰：「陳侯不有大咎，國必亡。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-15_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-15","order":2,"canonicalText":"」王曰：「何故？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-15_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-15","order":3,"canonicalText":"」對曰：「夫辰角見而雨畢，天根見而水涸，本見而草木節解，駟見而隕霜，火見而清風戒寒。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-15_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-15","order":4,"canonicalText":"此先王之教民以時也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-15_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-15","order":5,"canonicalText":"今陳侯荒怠不恤，必亡。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-15_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-15","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-16_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-16","order":1,"canonicalText":"「《周制》有之曰：『列樹以表道，立鄙食以守路，國有郊牧，疆有寓望，藪有圃草，囿有林池，所以備水旱也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-16_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-16","order":2,"canonicalText":"』今陳國廢其政，道路不通，水旱無備，何以能久？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-16_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-16","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-17_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-17","order":1,"canonicalText":"「周之《秩官》有之曰：『敵國賓至，關尹以告，行理以節逆之，候人為導，卿出郊勞，門尹除門，宗祝薦禮。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-17_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-17","order":2,"canonicalText":"』今陳國無賓禮，是棄交也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-17_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-17","order":3,"canonicalText":"棄交無援，亡之道也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-17_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-17","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-18_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-18","order":1,"canonicalText":"「先王之令有之曰：『天道賞善而罰淫，故凡我造國，無從非彝，無即慆淫，各守爾典，以承天休。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-18_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-18","order":2,"canonicalText":"』今陳侯淫亂於夏氏，棄其國典，是速其禍也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-18_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-18","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-19_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-19","order":1,"canonicalText":"「昔先王之教，懋帥其德也，猶恐殞越。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-19_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-19","order":2,"canonicalText":"若廢其教而棄其制，蔑其官而犯其令，將何以守國？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-19_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-19","order":3,"canonicalText":"居大國之間，而無政無德，陳必滅矣。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-19_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-19","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-20_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-20","order":1,"canonicalText":"六年，單子如楚。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-20_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-20","order":2,"canonicalText":"八年，陳侯殺於夏氏。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-20_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-20","order":3,"canonicalText":"九年，楚子入陳。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-20_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-20","order":4,"canonicalText":"單襄公之言皆驗。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-21_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-21","order":1,"canonicalText":"定王八年，使劉康公聘於魯，發幣於大夫。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-21_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-21","order":2,"canonicalText":"季文子、孟獻子皆儉，叔孫宣子、東門子家皆侈。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":1,"canonicalText":"歸，王問魯大夫孰賢？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":2,"canonicalText":"對曰：「季、孟其長處魯乎！","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":3,"canonicalText":"叔孫、東門其亡乎！","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":4,"canonicalText":"若家不亡，身必不免。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":5,"canonicalText":"」王曰：「何故？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":6,"canonicalText":"」對曰：「夫儉，德之共也；","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":7,"canonicalText":"侈，惡之大也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-8","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":8,"canonicalText":"季、孟恭儉以安其位，叔孫、東門驕侈以肆其志。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-9","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":9,"canonicalText":"驕侈必亡，自然之數也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-22_s-10","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-22","order":10,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-23_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-23","order":1,"canonicalText":"十六年，魯宣公卒。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-23_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-23","order":2,"canonicalText":"赴者未及，東門氏來告亂，子家奔齊。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-23_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-23","order":3,"canonicalText":"簡王十一年，魯叔孫宣伯亦奔齊，成公未歿而兩家皆敗，劉子之言皆驗。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-24_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-24","order":1,"canonicalText":"簡王八年，魯成公來朝，使叔孫僑如先聘且告。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-24_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-24","order":2,"canonicalText":"見王孫說，與之語。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-24_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-24","order":3,"canonicalText":"說言於王曰：「魯叔孫之來也，必有異謀，其言甘而動傲，傲則自肆，甘則欲得於人。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-24_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-24","order":4,"canonicalText":"肆必犯令，欲必害國。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-24_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-24","order":5,"canonicalText":"叔孫必不免於難。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-24_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-24","order":6,"canonicalText":"」後果如其言。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-25_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-25","order":1,"canonicalText":"晉既克楚於鄢，使郤至告慶於周。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-25_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-25","order":2,"canonicalText":"未將事，王叔簡公飲之酒，交酬好貨皆厚，飲酒宴語相說也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-26_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-26","order":1,"canonicalText":"明日，王孫子譽諸朝，郤至見邵桓公，與之語。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-26_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-26","order":2,"canonicalText":"邵公以告單襄公曰：「王叔子譽溫季，以為必相晉國，吾見之，其言狂而自伐，若不自損，恐不免於禍。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-26_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-26","order":3,"canonicalText":"」單襄公曰：「然，吾亦察之矣。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-26_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-26","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-27_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-27","order":1,"canonicalText":"「吾曰：『子則賢矣。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-27_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-27","order":2,"canonicalText":"抑晉國之舉也，不失其次，吾懼政之未及子也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-27_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-27","order":3,"canonicalText":"』謂我曰：『夫何次之有？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-27_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-27","order":4,"canonicalText":"昔先軫、欒枝、趙衰皆以功進，何次之守？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-27_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-27","order":5,"canonicalText":"吾今有大功於鄢，晉政其舍我其誰！","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-27_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-27","order":6,"canonicalText":"』此其自伐之甚也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-27_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-27","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-28_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-28","order":1,"canonicalText":"襄公曰：「人有言曰：『兵在其頸。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-28_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-28","order":2,"canonicalText":"』其郤至之謂乎！","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-28_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-28","order":3,"canonicalText":"君子不自稱也，非以讓也，惡其蓋人也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-28_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-28","order":4,"canonicalText":"夫人性陵上者兇，蓋人者怨。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-28_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-28","order":5,"canonicalText":"今郤至矜其伐而蓋其上，是速其死也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-28_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-28","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-29_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-29","order":1,"canonicalText":"「晉之克也，天有惡於楚也，故儆之以晉。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-29_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-29","order":2,"canonicalText":"而郤至佻天之功以為己力，不亦難乎？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-29_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-29","order":3,"canonicalText":"佻天不祥，乘人不義，不義不祥，將何以存？","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-29_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-29","order":4,"canonicalText":"其死必不久矣。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-29_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-29","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-30_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-30","order":1,"canonicalText":"郤至歸，明年死難。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-30_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-30","order":2,"canonicalText":"及伯輿之獄，王叔陳生奔晉。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-30_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-30","order":3,"canonicalText":"單襄公之言皆驗。","chunks":[],"tags":[]},{"id":"guo-yu_ch-2_p-30_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-2","passageId":"guo-yu_ch-2_p-30","order":4,"canonicalText":"周之史官，其知禮而明察興亡如此。","chunks":[],"tags":[]}]}');export{u as default};
